// --------------------------------------------------------------------------
// 展開並組裝全日時刻表
// --------------------------------------------------------------------------
function expandTrainRecord([tripCode, typeCode, dirCode, startSec, flatStops]) {
  const type = typeCode === "E" ? "express" : "commuter";
  const direction = dirCode === "S" ? "south" : "north";
  const stops = [];
  let currentSec = startSec;

  for (let i = 0; i < flatStops.length; i += 3) {
    const stationId = STATION_IDS[flatStops[i]];
    const runSec = flatStops[i + 1];
    const dwellTime = flatStops[i + 2];

    if (i > 0) {
      currentSec += runSec;
    }
    const arrSec = currentSec;
    const depSec = arrSec + dwellTime;
    currentSec = depSec;

    stops.push({
      stationId,
      arr: secToTime(arrSec),
      dep: secToTime(depSec),
      dwellTime
    });
  }

  const a8Stop = stops.find(s => s.stationId === "A8");

  return {
    tripCode,
    type,
    direction,
    originStation: stops[0].stationId,
    terminalStation: stops[stops.length - 1].stationId,
    departureTime: stops[0].dep,
    serviceDays: "all",
    hasWaitAtA8: Boolean(a8Stop && a8Stop.dwellTime >= 180),
    stops
  };
}

export function assembleSchedule({ isHoliday = false } = {}) {
  return ALL_TRAINS_RAW.map(expandTrainRecord).filter(train => {
    if (isHoliday && train.serviceDays === "weekday") return false;
    return true;
  });
}

// ⭐ 快取平日與假日組裝結果，避免重複運算
const weekdayTimetable = assembleSchedule({ isHoliday: false });
const holidayTimetable = assembleSchedule({ isHoliday: true });

export const fullDayTimetable = weekdayTimetable;

export function isWeekendOrHoliday(date = new Date()) {
  const day = date.getDay();
  return day === 0 || day === 6;
}

export function getFirstTrain(stationId, direction, options = {}) {
  const { type = null, date = new Date(), isHoliday = isWeekendOrHoliday(date) } = options;
  const timetable = isHoliday ? holidayTimetable : weekdayTimetable;

  const candidates = [];
  timetable.forEach(train => {
    if (train.direction !== direction) return;
    if (type && train.type !== type) return;

    const stop = train.stops.find(s => s.stationId === stationId);
    if (stop && stop.dep) {
      candidates.push({
        tripCode: train.tripCode,
        type: train.type,
        origin: train.originStation,
        terminal: train.terminalStation,
        depTime: stop.dep,
        depSec: timeToSec(stop.dep),
        dwellTime: stop.dwellTime || 0,
        serviceDays: train.serviceDays
      });
    }
  });

  if (candidates.length === 0) return null;
  candidates.sort((a, b) => a.depSec - b.depSec);
  return candidates[0];
}
